      "expected_value": "[\"delete\", \"create\"]"
    },
    {
      "claim": "the security group being created allows public internet access on ports 80 and 443, which is expected for a public API but should be confirmed as intentional",
      "rule": "R2",
      "evidence_pointer": "resource_changes[1].change.after.ingress[0].cidr_blocks[0]",
      "expected_value": "0.0.0.0/0"
    },
    {
      "claim": "the production load balancer replacement is a networking change that other resources depend on, as shown by the lb_listener resources referencing it",
      "rule": "R6",
      "evidence_pointer": "configuration.root_module.resources[0].expressions.load_balancer_arn.references[0]",
      "expected_value": "aws_lb.public_api.arn"
    }
  ],
